$(document).on("WebPlayerSeIniciaSistema",function(){var controles=ObtenerControles(["btnSiguiente","btnSiguienteBlock","btnAnterior"]);if(!controles||!controles.length){return;}
var rutaImagenes=Ciel.MPC.WebPlayer.RutaRecursos+"img/";var imgControles={"btnSiguiente":"icon_arrow_right.svg","btnSiguienteBlock":"icon_arrow_right.svg","btnAnterior":"icon_arrow_back.svg","default":"icon-help.svg"};controles.forEach(function(control){if(control.DivContenedor==undefined){return;}
var elemento=control.DivContenedor[0];if(!elemento){return;}
var rutaImagen=imgControles[control.Nombre];if(!rutaImagen){rutaImagen=imgControles["default"];}
var imgCola=document.createElement("img");imgCola.setAttribute('src',rutaImagenes+rutaImagen);var divContentImg=document.createElement("div");if(control.Nombre=="btnAnterior"){divContentImg.classList.add('contentImgBtnAnterior');divContentImg.append(imgCola);elemento.prepend(divContentImg);return;}
divContentImg.classList.add('contentImgBtnSiguiente');divContentImg.append(imgCola);elemento.append(divContentImg);});});